(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0004.js"] = [{"id":"glyph-kai-5f0a","script":"kai","character":"弊","reading":"bì","description":"bì：(1)欺蒙人的坏事作～。营私舞～。\n(2)害处，与利”相对～病。～端。～害。～政。利～。兴利除～。\n(3)败，疲困。\n(4)古同蔽”，隐蔽。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弊"},{"id":"glyph-kai-5f0f","script":"kai","character":"式","reading":"shì","description":"shì：(1)物体外形的样子～样。样～。\n(2)特定的规格格～。程～。\n(3)典礼，有特定内容的仪式开幕～。阅兵～。\n(4)自然科学中表明某些关系或规律的一组符号分子～。算～。公～。\n(5)一种语法范畴，表示说话者对所说事情的主观态度叙述～。命令～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-式"},{"id":"glyph-kai-5f13","script":"kai","character":"弓","reading":"gōng","description":"gōng：(1)射箭或发弹丸的器具～箭。～弩。飞鸟尽，良～藏。\n(2)像弓的器具或形态胡琴～子。～鞋。\n(3)旧时丈量地亩用的器具和计算单位。\n(4)弯曲～身。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弓"},{"id":"glyph-kai-5f15","script":"kai","character":"引","reading":"yǐn","description":"yǐn：(1)拉，伸～力。～颈。～而不发。～吭高歌。\n(2)领，招来～见。～子。～言。～导。～荐。抛砖～玉。\n(3)拿来做证据、凭据或理由～文。～用。援～。\n(4)退却～退。～避。\n(5)旧时长度单位，一引等于十丈。\n(6)古代柩车的绳索发～（出殡）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-引"},{"id":"glyph-kai-5f17","script":"kai","character":"弗","reading":"fú","description":"fú：不～去。～许。自愧～如。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弗"},{"id":"glyph-kai-5f18","script":"kai","character":"弘","reading":"hóng","description":"hóng：(1)大（现多用宏”）～愿。～图。～业。～谋。恢～（ａ．宽阔、广大，如气度～～”；ｂ．发扬，如～～士气”。亦作恢宏”）。\n(2)扩充，光大～扬。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弘"},{"id":"glyph-kai-5f1b","script":"kai","character":"弛","reading":"chí","description":"chí：(1)放松，松懈，解除松～。废～。～惰（懈怠）。～缓（局势、气氛等变和缓）。～张（张”，拉紧弓弦；弛”，放松弓弦，喻兴废、宽严、劳逸等）。\n(2)延缓～期。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弛"},{"id":"glyph-kai-5f1f","script":"kai","character":"弟","reading":"dì；tì；tuí","description":"dì：(1)同父母（或只同父、只同母）的比自己年纪小的男子～～。兄～。\n(2)亲戚或亲族间辈分相同的比自己年纪小的男子表～。堂～。\n(3)称同辈比自己年纪小的男性老～。师～。\n(4)学生对老师自称或别人指称～子。徒～。\n(5)古同第”，次序。\n(6)古同第”，但。\n兄；\ntì：古同悌”，孝悌。\n兄；\ntuí：〔～靡〕颓唐；柔顺。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弟"},{"id":"glyph-kai-5f20","script":"kai","character":"张","reading":"zhāng","description":"开弓;拉弓弦\n⒈将弦安在弓上。〈引〉拉开弓～弓。\n⒉乐器上弦改弦更～。\n⒊开，展开～开。～口。大～旗鼓。纲举目～。\n⒋伸展，扩大，夸大伸～。扩～。夸～。虚～声势。\n⒌放纵，无拘束乖～。气焰嚣～。\n⒍陈设，铺排大～筵席。铺～浪费。\n⒎看，望东～西望。\n⒏指商店开业开～。\n⒐量词两～床。四～报纸。\n⒑星宿名。二十八宿之一。\n①惊慌～皇失措。\n②夸大，炫耀～皇其词。\n①设罗网捕虫鸟。\n②料理，筹划，应酬烦你～罗照应。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-张"},{"id":"glyph-kai-5f25","script":"kai","character":"弥","reading":"mí","description":"充满;填满\n通弭”。停止\n遍;满\n⒉补，合～补。～合。\n⒊更加～坚。欲盖～彰。\n⒋长，久旷日～久。\n弥mǐ 1.通\"弭\"。止息。 2.通\"弭\"。末端。参见\"弥龙\"。 3.通\"靡\"。奢侈。参见\"弥侈\"。\n弥nǐ 1.水深满貌。 2.深水。 3.充满，遍布。 4.见\"弥迤\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弥"},{"id":"glyph-kai-5f26","script":"kai","character":"弦","reading":"xián","description":"xián：(1)系在弓背两端的、能发箭的绳状物弓～。～韦（弦”指弓弦，韦”是兽皮，弦紧皮软，喻性子急缓不同。古人佩弦来警戒自己的性缓，佩韦以警戒自己的性急；后遂用弦韦”喻朋友的规劝）。～月（农历每月初七、八或二十二、三，月亮半圆，形似弓弦，故名）。上～（农历每月初七或初八的月相）。下～（农历每月二十二或二十三的月相）。应～而倒。\n(2)乐器上发声的线琴～。～子（ａ．指琴弦；ｂ．乐器三弦”的通称）。～歌。管～。续～（古人以琴瑟喻夫妻，故又以断弦”喻丧妻，以续弦”喻再娶）。～外之音。\n(3)中国古代称不等腰直三角形的斜边。\n(4)中医脉象名～脉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弦"},{"id":"glyph-kai-5f27","script":"kai","character":"弧","reading":"hú","description":"hú：(1)古代指木弓桑～。～矢。弦木为～。\n(2)圆周的任意一段～形。～线。～度。电～。～光。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弧"},{"id":"glyph-kai-5f2f","script":"kai","character":"弯","reading":"wān","description":"折,使弯曲\n停船靠岸,停泊\n大爷吩咐急急收了口\n⒈屈曲，不直～曲。～腰。\n⒉曲折的部分～道。拐个～子。转左～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弯"},{"id":"glyph-kai-5f31","script":"kai","character":"弱","reading":"ruò","description":"ruò：(1)力气小，势力小，与强”相对～小。柔～。脆～。薄～。～不禁风。柔心～骨（形容人心地温柔，性格和顺）。\n(2)年纪小～冠（泛指男子二十岁左右的年纪）。\n(3)不够，差点儿，与强”相对三分之一～。\n(4)差，不如～于。～点。\n(5)丧失（指人死）又～了一个。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弱"},{"id":"glyph-kai-5f39","script":"kai","character":"弹","reading":"dàn","description":"形状像弹丸的东西,如圆形的果实;禽鸟的卵等\n弹弓\n炸弹\n①弹子；弹丸。\n②枪弹、炮弹、炸弹之类的总称。又见tán。\n【弹道导弹】'弹道式导弹'的简称。由火箭发动机推送到一定高度和一定速度后，发动机关闭，弹头沿着预定弹道飞向目标。\n【弹道曲线】炮弹飞行的轨迹。\n【弹道式导弹】见【弹道导弹】。\n【弹尽粮绝】见【弹尽援绝】。\n【弹尽援绝】弹药用尽，又得不到补给和救援。形容战事艰难，处境十分险恶。又作弹尽粮绝。\n【弹丸】\n①弹弓弹射所用的泥石小球或铁制小球。\n②比喻地方狭小～之地。\n⒈利用弹性射出弹丸等～击。\n⒉用手指拨弄，敲击。或手指受压后，用力伸出的动作～琴。～冠。～了他两下。\n⒊使振动～动。～棉花。\n⒋批评，抨击，检举评～。讥～。～劾。\n⒎［弹性］物体受外力后变形，外力一去即恢复原状的性能。〈引〉收缩性。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-弹"},{"id":"glyph-kai-5f3a","script":"kai","character":"强","reading":"qiáng；qiǎng；jiàng","description":"qiáng：(1)健壮，有力，与弱”相对～壮。～健。～人。～力。～大。～劲。刚～。富～。列～。～弩之末。年富力～。\n(2)程度高～手。～烈。～酸。能力～。\n(3)胜过，优越，好～干。争～好（hào）胜。\n(4)有余，略多于某数～半（超过一半）。\n(5)使用强力，硬性地～占。～加。～攻。～悍。～横（hèng）。～梁（强横霸道）。\n(6)着重，增加分量～化。增～。\n弱；\nqiǎng：硬要，迫使，尽力～使。～迫。～逼。～辩。勉～。～人所难。～词夺理。\n弱；\njiàng：固执，强硬不屈～嘴。倔～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-强"},{"id":"glyph-kai-5f52","script":"kai","character":"归","reading":"guī","description":"凡诸侯之女归宁曰来\n⒈回，返，回到～家团聚。～国华侨。回～祖国。〈引〉还给～还。物～原主。\n⒉趋向同～殊途。四海～心。\n⒊由，属于这件事～她办。\n⒋聚拢，并入～档。～并。颗粒～仓。\n⒌依附，附属～附。～属。\n⒍顺服，反正～顺。弃邪～正。\n⒎结局，结论～宿。～结。\n⒏除，珠算中一位数的除法三～。七～。\n归kuì 1.通\"馈\"。赠送。 2.通\"愧\"。惭愧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-归"},{"id":"glyph-kai-5f53","script":"kai","character":"当","reading":"dāng；dàng","description":"dàng：(1)合宜恰～。适～。妥～。\n(2)抵得上，等于一个人～俩人用。\n(3)姑且作为～做。长歌～哭。安步～车。\n(4)认为我～你已经回家了。\n(5)在同一时间～日。～年。～世。\n(6)吃亏，受骗上～。\n(7)抵押抵～。押～。典～（用实物作抵押向当铺借钱）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-当"},{"id":"glyph-kai-5f55","script":"kai","character":"录","reading":"lù","description":"记载言行事物的册籍\n次第,次序\n总领\n余之手录。\n⒈记载，登记～音。～功。\n⒉抄写抄～。摘～。\n⒊记载言行或事物的书刊、文本语～。回忆～。备忘～。\n⒋任用，采取～用。～取。收～。\n⒌审查并记载犯人的罪状～供。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-录"},{"id":"glyph-kai-5f62","script":"kai","character":"形","reading":"xíng","description":"xíng：(1)实体～仪（体态仪表）。～体。～貌。～容。～骸。～单影只。～影相吊。\n(2)样子～状。～式。～态。～迹。地～。情～。\n(3)表现～诸笔墨。喜～于色。\n(4)对照，比较相～见绌。\n(5)状况，地势～势。\n(6)古同型”，模子。\n(7)古同刑”，刑罚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-形"},{"id":"glyph-kai-5f64","script":"kai","character":"彤","reading":"tóng","description":"tóng：(1)红色～管（ａ．赤管笔，古代女史以此记事，后因用于女子文墨之事；ｂ．一说是红色管状的初生之草）。～云。～庭（中国汉代皇宫以朱红色漆中庭，后泛指皇宫）。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彤"},{"id":"glyph-kai-5f69","script":"kai","character":"彩","reading":"cǎi","description":"cǎi：(1)各种颜色交织～云。～虹。～霞。～绘。～陶。～绸。～笔。～车。～蛋（ａ．画在鸡、鸭蛋壳上的工艺品；ｂ．方言，松花蛋）。～灯。五～缤纷。\n(2)五色的绸子剪～。\n(3)指赌博或某种竞赛中赢得的东西～金。～票。得～。\n(4)称赞、夸奖的欢呼声喝（hè）～。\n(5)花样，完美的成分丰富多～。文～。\n(6)喻战士受伤流的血挂～。～口。\n(7)指彩金～券。中（zhòng）～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彩"},{"id":"glyph-kai-5f6a","script":"kai","character":"彪","reading":"biāo","description":"biāo：(1)虎身上的斑纹，引申为有文采～炳。\n(2)小老虎。\n(3)身躯魁悟～悍。～壮。～形大汉。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彪"},{"id":"glyph-kai-5f6c","script":"kai","character":"彬","reading":"bīn","description":"bīn：〔～～〕形容文雅，如～～有礼”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彬"},{"id":"glyph-kai-5f6d","script":"kai","character":"彭","reading":"péng；bāng","description":"péng：姓。\nbāng：〔～～〕ａ．众多的样子，如行人～～”；ｂ．雄壮有力的样子，如四牡～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彭"},{"id":"glyph-kai-5f70","script":"kai","character":"彰","reading":"zhāng","description":"zhāng：(1)明显，显著～～。昭～。～明。欲盖弥～。\n(2)表明，显扬表～。～善瘅恶（表扬好的，憎恨坏的）。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彰"},{"id":"glyph-kai-5f71","script":"kai","character":"影","reading":"yǐng","description":"yǐng：(1)物体挡住光线时所形成的四周有光中间无光的形象，亦指不真切的形象或印象人～。花～。倒～。幻～。～壁。～响。～射（借甲指乙，或暗指某人其事）。无～无踪。～～绰绰（模凝糊，不真切）。捕风捉～‖沙射～（喻暗地里诽谤中伤）。\n(2)形象摄～（照相）。留～。剪～。～印。～像。\n(3)描摹～写。～抄。～宋本。\n(4)指电影”～评。～院。～片。～视（电影和电视）。～坛。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-影"},{"id":"glyph-kai-5f79","script":"kai","character":"役","reading":"yì","description":"yì：(1)服兵务，从军从～。现～。\n(2)战事战～。\n(3)服劳力之事劳～。徭～。\n(4)使唤～使。奴～。\n(5)被役使的人～夫。～徒。仆～。杂～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-役"},{"id":"glyph-kai-5f7b","script":"kai","character":"彻","reading":"chè","description":"拆毁;拆下\n彻 chè通；透响～云霄、～夜不眠。\n【彻骨】渗进骨头里。形容程度极深。\n【彻头彻尾】从头到尾；完全彻底。\n⒉〈古〉通\"撤\"～退。～去。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彻"},{"id":"glyph-kai-5f7c","script":"kai","character":"彼","reading":"bǐ","description":"bǐ：(1)那，那个～岸。此起～伏。\n(2)他，对方知己知～。～此。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-彼"},{"id":"glyph-kai-5f80","script":"kai","character":"往","reading":"wǎng","description":"wǎng：(1)去，到～返。～复。～还（huán）。～来。交～。向～。勇～直前。\n(2)过去～昔。～日。～事。～古。～常。以～。一如既～。\n(3)同望”⑤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-往"},{"id":"glyph-kai-5f81","script":"kai","character":"征","reading":"zhēng","description":"⒉讨伐，用武力制服～讨。～服。南～北战。\n⒊争夺，夺取力～。\n⒋召集，收用～召。～集。～收。～用。～税。～调。～兵。\n⒌找请，寻求～聘。～求。～文。～询意见。\n⒍证明，证验有～。实物可～。\n⒎现象，迹象～象。～兆。特～。\n征chéng 1.通\"惩\"。警戒;惩罚。 2.古地名。在今陕西省澄城县。\n征zhǐ 1.古五音之一。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-征"},{"id":"glyph-kai-5f84","script":"kai","character":"径","reading":"jìng","description":"经过,行经\n南北为径\n夫惟捷径以窘步。\n⒈小路山～。曲～。〈引〉取道，经过夜～泽中。〈喻〉达到目的之方法找门～。取捷～。\n⒉直往，直接，直截了当～往。～自去。～向对方联系。\n⒊［直径］两端以圆周为界，经过圆心的直线。又称直径的长度井口～三尺。\n⒋［半径］圆心到圆周的直线。\n径jīng 1.经过;行经。 2.南北为径。参见\"径轮\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-径"},{"id":"glyph-kai-5f85","script":"kai","character":"待","reading":"dài；dāi","description":"dài：(1)等，等候～到。～旦。拭目以～。\n(2)以某种态度或行为加之于人或事物对～。招～。～遇。～人接物。\n(3)将，要（古典戏曲小说和现代某些方言的用法）正～出门，有人来了。\ndāi：停留，逗留，迟延你～一会儿再走。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-待"},{"id":"glyph-kai-5f88","script":"kai","character":"很","reading":"hěn","description":"hěn：(1)甚，非常，表示程度加深～快。～好。\n(2)古同狠”，凶恶。\n(3)古代指争讼～无求胜”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-很"},{"id":"glyph-kai-5f8a","script":"kai","character":"徊","reading":"huái","description":"huái：〔徘（pái）～〕见徘”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-徊"},{"id":"glyph-kai-5f8b","script":"kai","character":"律","reading":"lǜ；lv","description":"lǜ：(1)法则，规章纪～。法～。定～。规～。清规戒～。～师。\n(2)约束～己。\n(3)中国古代审定乐音高低的标准，把声音分为六律（阳律）和六品（阴律）∠称十二律”～吕（古代用竹管制成的校正乐律的器具，以管的长短来确定音的不同高度，从低音管算起，成奇数的六个管称律”；成偶数的六个管称吕”，后来律吕”作为音律的统称）。\n(4)旧诗的一种体裁～诗。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-律"},{"id":"glyph-kai-5f90","script":"kai","character":"徐","reading":"xú","description":"xú：(1)缓，慢慢地～步。～缓。～图。～～。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-徐"},{"id":"glyph-kai-5f92","script":"kai","character":"徒","reading":"tú","description":"tú：(1)步行～步。～涉。\n(2)空～手。\n(3)白白地～然。～劳无益。\n(4)只；仅仅家～四壁。\n(5)从事学习的人～弟。～工。学～。师～。\n(6)同一派系或信仰同一宗教的人信～。教～。党～。\n(7)人（多指坏人）匪～。暴～。赌～。叛～。\n(8)剥夺犯人自由的刑法～刑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-徒"},{"id":"glyph-kai-5f97","script":"kai","character":"得","reading":"dé；děi；de","description":"dé：得到、获得；适合。děi：需要，必须。de：助词，连接动作与补语，如写得好。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-5f98","script":"kai","character":"徘","reading":"pái","description":"pái：〔～徊〕ａ．来回地走，如他在那里～～了很久”；ｂ．犹疑不决，如左右～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-徘"},{"id":"glyph-kai-5f99","script":"kai","character":"徙","reading":"xǐ","description":"xǐ：(1)迁移～居（搬家）。迁～。流～。\n(2)古代称流放的刑罚～边（流放有罪的人到边远地区）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-徙"},{"id":"glyph-kai-5fa1","script":"kai","character":"御","reading":"yù","description":"后亦泛指驾驭一切运行或飞行之物\n御轻舟而上溯,\n⒈驾驭车马～车。又指驾驭车马的人～手。\n⒊称与皇帝有关的～衣。～旨。～用。～河桥。\n⒋侍奉，敬献～于君。～欲王公。\n⒌抵挡，阻止～敌。抵～。～风寒。\n御yà 1.迎接。 2.向;面向。 3.逢迎;迎合。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-御"},{"id":"glyph-kai-5faa","script":"kai","character":"循","reading":"xún","description":"xún：(1)遵守，依照沿袭遵～。因～。～环。～规蹈矩。\n(2)古同巡”，巡行。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-循"},{"id":"glyph-kai-5fae","script":"kai","character":"微","reading":"wēi","description":"wēi：(1)小，细小细～。轻～。～小。～型。～观。～雕。～积分。～电脑。～量元素。谨小慎～。～乎其～。\n(2)少；稍稍～。～笑。～调（tiáo）。\n(3)衰落；低下卑～。～贱。\n(4)精深；精妙～妙。精～。～言大义。\n(5)隐约；不明～茫。～词（隐晦的批评）。\n(6)隐匿白公奔山而缢，其徒～亡”。\n(7)暗中察访～行。\n(8)无，非～斯人，吾谁与归”。\n(9)与某一物理量的单位连用时，表示该量的百万分之一～米（公制长度单位，米”的百万分之一）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-微"},{"id":"glyph-kai-5fb7","script":"kai","character":"德","reading":"dé","description":"dé：(1)人们共同生活及行为的准则和规范，品行，品质美～。品～。公～。～行。道～。～性。～育（以一定的社会要求，进行思想的、政治的和道德的教育）。～才兼备。度～量力。～高望重。\n(2)心意，信念一心一～。\n(3)恩惠～施。～泽（德化和恩惠）。～惠。感恩戴～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-德"},{"id":"glyph-kai-5fbd","script":"kai","character":"徽","reading":"huī","description":"huī：(1)标志，符号国～。校～。帽～。～章。～记。～帜（zhì）。\n(2)美好的～号。\n(3)系琴弦的绳，后用做抚琴标记的名称，古琴全弦共十三徽。\n〔～州〕旧地名，在今中国安徽省歙县。简称徽”，如～墨”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-徽"},{"id":"glyph-kai-5fc3","script":"kai","character":"心","reading":"xīn","description":"xīn：(1)人和高等动物体内主管血液循环的器官（通称心脏”）～包。～律。～衰。～悸。\n(2)中央，枢纽，主要的～腹。中～。\n(3)习惯上指思想的器官和思想情况，感情等～理。～曲。～魄。～地。～扉。衷～。～旷神怡。人～惟危。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-心"},{"id":"glyph-kai-5fc5","script":"kai","character":"必","reading":"bì","description":"bì：(1)一定～定。～然。～须（一定要）。～需（不可少的）。势～。未～。事～躬亲。\n(2)决定，肯定深念远虑兮，胜乃可～”。\n(3)固执毋意，毋～”。\n(4)果真，假使王～无人，臣愿奉璧往使”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-必"},{"id":"glyph-kai-5fc6","script":"kai","character":"忆","reading":"yì","description":"留在记忆中;记住\n回忆\n忆昔抚今\n忆昔抚今,思绪万千\n⒈思念，回想～念。思～。回～。～故乡。\n⒉记住，记得记～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忆"},{"id":"glyph-kai-5fcc","script":"kai","character":"忌","reading":"jì","description":"jì：(1)嫉妒，憎恨猜～。～才。～能。～妒。～贤妒能。\n(2)害怕，畏惧顾～。肆无～惮。\n(3)禁戒～戒。～食。～讳。禁～。\n(4)父母或祖先死亡的日子，迷信称不吉利的日子～日。～辰。生～（已死父母的生日）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忌"},{"id":"glyph-kai-5fcd","script":"kai","character":"忍","reading":"rěn","description":"rěn：(1)耐，把感情按住不让表现～耐。～痛。～受。容～。～俊不禁（忍不住笑）。\n(2)狠心，残酷～心。残～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忍"},{"id":"glyph-kai-5fd7","script":"kai","character":"志","reading":"zhì","description":"zhì：(1)意向～愿。～气。～趣（志向和兴趣）。～士（有坚决意志和高尚节操的人）。～学。\n(2)记，记在心里～喜。～哀。永～不忘。\n(3)记号标～。\n(4)记载的文字杂～。～怪（记载怪异的事）。\n(5)称轻重，量长短、多少～子。用碗～～。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-志"},{"id":"glyph-kai-5fd8","script":"kai","character":"忘","reading":"wàng","description":"wàng：不记得，遗漏～记。～却。～怀。～我。～情。～乎所以。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忘"},{"id":"glyph-kai-5fd9","script":"kai","character":"忙","reading":"máng","description":"máng：(1)事情多，没空闲～乱。～活。～碌。手～脚乱。\n(2)急迫，急速地做～于（忙着做某方面的事情）。不慌不～。\n(3)旧时田赋分期征收称分忙”，有上～”、下～”之称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忙"},{"id":"glyph-kai-5fe0","script":"kai","character":"忠","reading":"zhōng","description":"zhōng：诚心尽力～心。～诚。～实。～告。～于。～魂。～义。～贞。效～。赤胆～心。～言逆耳。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忠"},{"id":"glyph-kai-5fe7","script":"kai","character":"忧","reading":"yōu","description":"忧其民。\n⒈发愁，担心～愁。担～。～心如焚。\n⒉可忧愁的事～患。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忧"},{"id":"glyph-kai-5feb","script":"kai","character":"快","reading":"kuài","description":"kuài：(1)速度大，与慢”相对～车。～件。～步。～速。～捷。～马加鞭。\n(2)赶紧，从速赶～。\n(3)将，就要；接近天～亮了。\n(4)灵敏他脑子真～。眼明手～。\n(5)锐利，锋利，与钝”相对王麻子刀剪真～。\n(6)爽利，直截了当爽～。心直口～。～人～语。\n(7)高兴舒服～乐。～意。痛～。愉～。～感。～事。～慰。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-快"},{"id":"glyph-kai-5ff1","script":"kai","character":"忱","reading":"chén","description":"chén：(1)真诚的情意热～。\n(2)诚恳～挚。～辞。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忱"},{"id":"glyph-kai-5ff5","script":"kai","character":"念","reading":"niàn","description":"niàn：(1)惦记，常常想惦～。怀～。～头（思想、想法）。悼～。～旧。～物。\n(2)心中的打算，想法，看法意～。杂～。信～。\n(3)说，读，诵读～白（戏剧道白）。～叨。～经。～书。\n(4)廿”的大写。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-念"},{"id":"glyph-kai-5ffd","script":"kai","character":"忽","reading":"hū","description":"hū：(1)粗心，不注意～视。疏～。～略。玩～职守。\n(2)迅速，突然～而。～然。～地。～高～低。\n(3)长度和重量单位（十忽为一丝，十丝为一毫）～微（极言细微）。微～其微。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忽"},{"id":"glyph-kai-5fff","script":"kai","character":"忿","reading":"fèn","description":"fèn：生气，恨～恨。～怒。～詈（因愤怒而骂）。不～（不服气，不平）。气不～（看到不平的事，心中不服气）。～～不平。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-忿"},{"id":"glyph-kai-6000","script":"kai","character":"怀","reading":"huái","description":"维以不永怀。\n心里存有;怀藏\n⒈胸前抱在～里。\n⒉想念～念故乡。～旧友。\n⒊心意，胸怀正中下～。襟～坦白。\n⒋揣着，包藏～抱。～疑。～恨。～怒未发。\n⒌怀胎母之～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怀"},{"id":"glyph-kai-6001","script":"kai","character":"态","reading":"tài","description":"⒈形状，样子形～。体～。状～。常～。姿～。\n⒉情况事～。\n①说话与举止的神情～度自然。\n②对人对事所采取的立场或看法～度傲慢。表明～度。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-态"},{"id":"glyph-kai-600e","script":"kai","character":"怎","reading":"zěn","description":"zěn：疑问词，如何～的。～么。～办。～奈（无奈）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怎"},{"id":"glyph-kai-6012","script":"kai","character":"怒","reading":"nù","description":"nù：(1)生气，气愤～色。～视。～叱。～骂。恼～。息～。\n(2)气势盛～涛。～火。心花～放。\n(3)中国少数民族，主要分布于云南省～族。\n(4)谴责若不可教而后～之”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怒"},{"id":"glyph-kai-6014","script":"kai","character":"怔","reading":"zhēng","description":"zhēng：〔～忪〕惊惧。\n〔～忡〕中医指心悸。\n〔～营〕惶恐不安。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怔"},{"id":"glyph-kai-6015","script":"kai","character":"怕","reading":"pà","description":"pà：(1)恐惧～人。～死ˇ～。惧～。可～。\n(2)或许，表示疑虑或猜想恐～他别有用意。～是。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怕"},{"id":"glyph-kai-6016","script":"kai","character":"怖","reading":"bù","description":"bù：惧怕～栗。～惧。恐～。情景可～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怖"},{"id":"glyph-kai-601c","script":"kai","character":"怜","reading":"lián","description":"爱,惜\n⒈同情～惜。～悯。\n⒉爱惜～爱。\n①可爱百花高楼更可～。\n②值得同情可～身上衣正单。\n怜líng 1.见\"怜悧\"﹑\"怜牙悧齿\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怜"},{"id":"glyph-kai-601d","script":"kai","character":"思","reading":"sī；sāi","description":"sī：(1)想，考虑，动脑筋～想（ａ．客观存在反映在人的意识中经过思维活动而产生的结果；ｂ．想法，念头；ｃ．思量）。～忖。～索。～维。沉～。寻～。见异～迁。\n(2)想念，挂念～念。～恋。相～。\n(3)想法～绪。～致（新颖独到的构思、意趣）。构～。\n(4)姓。\n念；想；\nsāi：〔于～〕多胡须的样子，如自捋颔下，则～～者如故矣”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-思"},{"id":"glyph-kai-6020","script":"kai","character":"怠","reading":"dài","description":"dài：(1)懒惰，忪懈～惰。～倦。～工。懈～。\n(2)轻慢，不尊敬～傲。～慢。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怠"},{"id":"glyph-kai-6021","script":"kai","character":"怡","reading":"yí","description":"yí：和悦，愉快～色（容色和悦）。～声（语声和悦）。～和。～乐（lè）。～神。～悦。～目（快意于所见，悦目）。心旷神～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怡"},{"id":"glyph-kai-6025","script":"kai","character":"急","reading":"jí","description":"jí：(1)焦燥～燥。着～。焦～。\n(2)气恼，发怒～眼。\n(3)使着急这件事真～人。\n(4)匆促～促。～功近利（急于求目前的成效和利益）。\n(5)迅速，又快又猛～流。～进。～先锋。～风暴雨。\n(6)迫切，要紧～切。～诊。～事。\n(7)严重告～。\n(8)对大家的事情或别人的困难尽快帮助～人之难。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-急"},{"id":"glyph-kai-6027","script":"kai","character":"性","reading":"xìng","description":"xìng：(1)人或事物的本身所具有的能力、作用等～质。～格。～命（生命）。～能。个～。属～。\n(2)性质，思想、感情等方面的表现典型～。开放～。指令～。\n(3)男女或雌雄的特质～别。男～。女～。\n(4)有关生物生殖的～交。～欲。～爱。～感。～解放。\n(5)表示名词（以及代词、形容词）的类别的语法范畴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-性"},{"id":"glyph-kai-6028","script":"kai","character":"怨","reading":"yuàn","description":"yuàn：(1)仇恨～恨。恩～。宿～。～仇。～敌。～府（大家怨恨的对象）。～声载道。\n(2)不满意，责备埋（mán）～。抱～。～言。任劳任～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怨"},{"id":"glyph-kai-602a","script":"kai","character":"怪","reading":"guài","description":"guài：(1)奇异，不平常～诞（离奇古怪）。～事。～物。～讶。～圈（quān）。～话。～异。奇形～状。\n(2)惊奇大惊小～。～不得。\n(3)传说中的妖魔之类鬼～。妖～。\n(4)性情乖僻或行为异样的人～癖（古怪的癖好）。～僻（古怪）。\n(5)很，非常～好的天气。\n(6)怨，责备不～你。～罪。～怨。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怪"},{"id":"glyph-kai-602f","script":"kai","character":"怯","reading":"qiè","description":"qiè：(1)胆小，没勇气～场。～懦。～弱。～步。～阵。羞～。\n(2)俗气，见识不广，不合时宜露～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-怯"},{"id":"glyph-kai-603b","script":"kai","character":"总","reading":"zǒng","description":"聚合;汇集\n无总\n⒈全，全部，主要的，为首的～的。～纲。～则。～统。～指挥。～司令。\n⒉聚合，汇集～括。～共。～计。\n⒊一直，经常她～爱笑。他～是吃苦在前。\n⒋一定，毕竟～会胜利。这件事～要办理。\n⒌统领～兵西下。\n①终究，终于～算成功了。\n②勉强，还可以这孩子能做到这样，～算不错了。\n总zōng 1.丝数名。古以丝八十根为\"总\"。\n总cōng 1.通\"纒\"。绢的一种。 2.通\"恠\"。参见\"总至\"。 3.通\"葱\"。参见\"总极\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-总"},{"id":"glyph-kai-6043","script":"kai","character":"恃","reading":"shì","description":"恃shì依靠，依赖，倚仗有～无恐。～才傲物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恃"},{"id":"glyph-kai-604b","script":"kai","character":"恋","reading":"liàn","description":"思念,怀念\n男女相爱\n⒈思念不忘，不忍分离留～。依～。思～难忘。～ ～不能舍。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恋"},{"id":"glyph-kai-604d","script":"kai","character":"恍","reading":"huǎng","description":"huǎng：(1)忽然～然大悟。\n(2)仿佛～如隔世。～惚。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恍"},{"id":"glyph-kai-6050","script":"kai","character":"恐","reading":"kǒng","description":"kǒng：(1)害怕，畏惧～惧。～怖。～慌。惊～。有恃无～。\n(2)恫吓（hè）～吓（hè）。\n(3)疑虑～怕。～不能成功。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恐"},{"id":"glyph-kai-6052","script":"kai","character":"恒","reading":"héng","description":"héng：(1)持久～心。～久。～定。～齿。永～。～星。～温。\n(2)经常的，普通的～言。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恒"},{"id":"glyph-kai-6055","script":"kai","character":"恕","reading":"shù","description":"shù：(1)原谅，宽容～宥。～谅。～罪。宽～。饶～。～我直言。\n(2)以自己的心推想别人的心～道。忠～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恕"},{"id":"glyph-kai-6062","script":"kai","character":"恢","reading":"huī","description":"huī：弘大，发扬～张。～弘。～廓。\n〔～复〕变成原来的样子，如健康已经～～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恢"},{"id":"glyph-kai-6064","script":"kai","character":"恤","reading":"xù","description":"xù：(1)对别人表同情，怜悯～刑（施刑慎重，不严刑以逼供）。体～。\n(2)救济～金。抚～。\n(3)忧虑～～（忧虑的样子）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恤"},{"id":"glyph-kai-6068","script":"kai","character":"恨","reading":"hèn","description":"hèn：(1)怨，仇视怨～。愤～。仇～。痛～。\n(2)为做不到或做不好而内心不安～事。悔～。遗～。抱～终天。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恨"},{"id":"glyph-kai-6069","script":"kai","character":"恩","reading":"ēn","description":"ēn：好处，深厚的情谊～爱。～赐。～宠（指帝王对臣下的优遇和宠幸）。～德。～典。～惠。～仇。感～。开～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恩"},{"id":"glyph-kai-606c","script":"kai","character":"恬","reading":"tián","description":"tián：安静，安然，坦然～静。～适。～然。～谧。～淡（淡泊名利，清静无为）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恬"},{"id":"glyph-kai-606d","script":"kai","character":"恭","reading":"gōng","description":"gōng：肃敬，谦逊有礼貌～敬。～谨。～候。～维。～贺。打～（拱揖）。洗耳～听。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恭"},{"id":"glyph-kai-606f","script":"kai","character":"息","reading":"xī","description":"xī：(1)呼吸时进出的气鼻～。喘～。叹～。窒～。瞬～万变。\n(2)停止，歇休～。歇～。～怒。～兵。～事宁人。～止。平～。偃旗～鼓。\n(3)繁殖，滋生休养生～。滋～。\n(4)音信消～。信～。\n(5)儿女子～。\n(6)利钱～率（lǜ）。利～。月～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-息"},{"id":"glyph-kai-6070","script":"kai","character":"恰","reading":"qià","description":"qià：(1)正巧，刚刚～巧。～好。～～（ａ．刚好，如～～相反”；ｂ．融和，如春光～～”；ｃ．鸟鸣声，如自在娇莺～～啼”）。～似。\n(2)合适，适当～当。～切（qiè）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恰"},{"id":"glyph-kai-6073","script":"kai","character":"恳","reading":"kěn","description":"请求,表露愿望和要求","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恳"},{"id":"glyph-kai-6076","script":"kai","character":"恶","reading":"è；wù；wū","description":"è：(1)不好～感。～果。～劣。～名。丑～。\n(2)凶狠～霸。～棍。险～。凶～。\n(3)犯罪的事，极坏的行为～贯满盈。\n好；美；爱；善；\nwù：讨厌，憎恨，与好（hào）”相对可～。厌～∶（hào）～。\n好；美；爱；善；\n（噁）\ně：〔～心〕要呕吐的感觉；亦指对人和事的厌恶态度。\n好；美；爱；善；\nwū：(1)古同乌”，疑问词，哪，何。\n(2)文言叹词，表示惊讶～，是何言也！","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恶"},{"id":"glyph-kai-607c","script":"kai","character":"恼","reading":"nǎo","description":"懊恼;烦闷\n⒈忿恨，发怒可～。～羞成怒。\n⒉忧愁，烦闷苦～。烦～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-恼"},{"id":"glyph-kai-6084","script":"kai","character":"悄","reading":"qiāo；qiǎo","description":"qiǎo：(1)忧愁～切。～怆。～然落泪。忧心～～。\n(2)寂静无声～然无声。～寂。～静。～声。\nqiāo：没有声音或声音很低，不让人知道深夜静～～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悄"},{"id":"glyph-kai-6089","script":"kai","character":"悉","reading":"xī","description":"xī：(1)知道洞～（很清楚地知道）。尽～。获～。来函敬～。\n(2)尽，全～力。～心。～数（shù）。～数（shǔ）（完全列举，如不可～～”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悉"},{"id":"glyph-kai-608d","script":"kai","character":"悍","reading":"hàn","description":"hàn：(1)勇猛，勇敢强～。精～。～勇。\n(2)凶暴～然。凶～。～吏。～戾。\n(3)强劲，急暴湍～。急～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悍"},{"id":"glyph-kai-6094","script":"kai","character":"悔","reading":"huǐ","description":"huǐ：懊恼过去做得不对后～。懊～。～改。～恨。～悟。追～莫及。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悔"},{"id":"glyph-kai-6096","script":"kai","character":"悖","reading":"bèi","description":"bèi：(1)混乱，相冲突～乱。～逆。～异。～论。并行不～。\n(2)惑，违背道理，谬误～谬。～惑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悖"},{"id":"glyph-kai-609f","script":"kai","character":"悟","reading":"wù","description":"wù：理解，明白，觉醒醒～。领～。参（cān）～。感～。觉～。大彻大～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悟"},{"id":"glyph-kai-60a0","script":"kai","character":"悠","reading":"yōu","description":"yōu：(1)久，远，长～久。～远。～扬。\n(2)在空中摆动～荡。晃～。转～。\n(3)稳住，控制～着点劲。\n(4)闲适，闲散～闲。～然。～忽（形容悠闲懒散）。～缓。～～（ａ．闲适，自由自在，如白云～～”；ｂ．忧郁，如～～我思”；ｃ．长久，遥远，如～～长夜”；ｄ．众多；ｅ．荒谬，如～～之谈”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悠"},{"id":"glyph-kai-60a3","script":"kai","character":"患","reading":"huàn","description":"huàn：(1)忧虑～得～失。忧～。\n(2)灾祸～难。祸～。隐～。防～未然。\n(3)害病～病。～者。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-患"},{"id":"glyph-kai-60a6","script":"kai","character":"悦","reading":"yuè","description":"yuè：(1)高兴，愉快喜～。愉～⊥颜～色。心～诚服。取～于人。\n(2)使愉快～耳。赏心～目。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悦"},{"id":"glyph-kai-60a8","script":"kai","character":"您","reading":"ní；nín","description":"nín：你”的敬称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-您"},{"id":"glyph-kai-60ac","script":"kai","character":"悬","reading":"xuán","description":"牵挂;挂念\n凭空设想;揣测\n⒈吊，挂～挂。～灯。～梁刺股。\n⒉挂念，惦记，关切的心情～念。\n⒊无着落，没结果～案。～而未决。\n⒋无依据，凭空揣度～断。～揣。\n⒌距离远～隔。～殊。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悬"},{"id":"glyph-kai-60af","script":"kai","character":"悯","reading":"mǐn","description":"忧愁;烦闷\n⒈哀怜～惜。怜～。\n⒉忧愁。忧患。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悯"},{"id":"glyph-kai-60b2","script":"kai","character":"悲","reading":"bēi","description":"bēi：(1)伤心，哀痛～哀。～伤。～怆。～痛。～切。～惨。～凉。～愤。～凄。～恸。～吟。～壮。～观。～剧。乐极生～。\n(2)怜悯～天悯人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悲"},{"id":"glyph-kai-60b4","script":"kai","character":"悴","reading":"cuì","description":"cuì：(1)忧伤人力雕残，百姓愁～”。\n(2)衰弱，疲萎憔～。～容。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悴"},{"id":"glyph-kai-60bc","script":"kai","character":"悼","reading":"dào","description":"dào：悲伤，哀念哀～。追～。～念。～亡。～唁。～词。～惜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-悼"},{"id":"glyph-kai-60c5","script":"kai","character":"情","reading":"qíng","description":"qíng：(1)外界事物所引起的喜、怒、爱、憎、哀、惧等心理状态感～。～绪。～怀。～操。～谊。～义。～致。～趣。～韵。性～。～愫（真情实意）。～投意合。～景交融。\n(2)专指男女相爱的心理状态及有关的事物爱～。～人。～书。～侣。～诗。殉～。～窦初开（形容少女初懂爱情）。\n(3)对异性的欲望，性欲～欲。发～期。\n(4)私意～面。说～。\n(5)状况实～。事～。国～。～形。～势。～节。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-情"},{"id":"glyph-kai-60ca","script":"kai","character":"惊","reading":"jīng","description":"惊动;震惊\n⒈骡、马等因受吓而发狂乱奔控制～马。〈引〉害怕，精神紧张～骇。～慌失措。～心动魄。～恐万状。\n⒉意料以外的感觉～喜交集。倍感～奇。\n⒊扰乱，震动～扰。～动。～天动地。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惊"},{"id":"glyph-kai-60cb","script":"kai","character":"惋","reading":"wǎn","description":"wǎn：叹惜，憾恨～惜。～伤。～叹。悲～。哀～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惋"},{"id":"glyph-kai-60d1","script":"kai","character":"惑","reading":"huò","description":"huò：(1)心疑不定，不明白对还是不对疑～。困～。惶～。智者不～。\n(2)使迷乱迷～。～乱。～人耳目。蛊～人心。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惑"},{"id":"glyph-kai-60d5","script":"kai","character":"惕","reading":"tì","description":"tì：(1)戒惧，小心谨慎警～。～惧。～～。～厉（心怀戒惧。亦作惕砺”）。\n(2)疾速一日～，一日留”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惕"},{"id":"glyph-kai-60dc","script":"kai","character":"惜","reading":"xī","description":"xī：(1)爱，重视爱～。顾～。怜～。珍～。\n(2)舍不得吝～。～别。～力。～指失掌（喻因小失大）。～墨如金。\n(3)感到遗憾，哀痛可～。～悯。惋～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惜"},{"id":"glyph-kai-60df","script":"kai","character":"惟","reading":"wéi","description":"wéi：(1)单，只～独。～一。～有。～恐。～命是从。～我独尊。\n(2)但是雨虽止，～路仍甚泥泞。\n(3)文言助词，常用于句首～妙～肖。～二月既望。\n(4)想，思考思～（亦作思维”）。～度（duó）（思量，揣度）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惟"},{"id":"glyph-kai-60e0","script":"kai","character":"惠","reading":"huì","description":"huì：(1)恩，好处恩～。～泽。～和。～爱。～握（恩惠深厚）。仁～。实～。施～于人。\n(2)给人财物或好处～政。互～互利。～及远人。～而不费（给人好处自己又没有什么耗费；常用以形容有实利而不多费钱财）。\n(3)敬辞，用于对方对待自己的行动～赠。～临。～顾。～存。～允。\n(4)古同慧”，聪明。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惠"},{"id":"glyph-kai-60e6","script":"kai","character":"惦","reading":"diàn","description":"diàn：记挂～念。～记。～挂。老～着工作。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惦"},{"id":"glyph-kai-60e7","script":"kai","character":"惧","reading":"jù","description":"害怕，恐惧，如畏惧、惧怕。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-kai-60e8","script":"kai","character":"惨","reading":"cǎn","description":"悲痛;伤心\n①悲惨；凄惨～状。\n②程度严重～败。\n③凶恶；狠毒～无人道。\n【惨不忍睹】悲惨得令人看不下去。睹看见。\n【惨怛】悲哀伤心的样子。\n【惨淡经营】费尽苦心从事某种工作或事业。惨淡境况困难或苦思极虑。经营规划从事。\n【惨景】悲惨的情形。\n【惨境】悲惨的境地。\n【惨剧】惨痛的事件。\n【惨无人道】残忍凶恶得连一点人性都没有。形容凶恶狠毒到了极点。\n【惨笑】内心痛苦、烦恼而勉强作出笑容。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惨"},{"id":"glyph-kai-60e9","script":"kai","character":"惩","reading":"chéng","description":"处罚\n改定\n克制;制止\n①处罚～处。\n②警戒～前毖后。\n【惩恶劝善】惩罚坏人，奖励好人。\n【惩戒】通过惩罚来达到警戒的目的。\n【惩前毖后】以过去的教训为警戒，谨防以后重犯错误。毖使谨慎。\n⒈警戒～前毖后。\n⒉责罚，处罚～罚。～办。严～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惩"},{"id":"glyph-kai-60eb","script":"kai","character":"惫","reading":"bèi","description":"衰竭;危殆\n惫懒\n①疲乏;困顿。\n②衰竭;危殆。\n③劣;坏。\n【憊懶】见\"憊賴\"。\n【憊老】衰老。\n【憊色】憔悴的颜色。\n【憊衿】惫赖秀才。\n【憊倦】疲惫劳累。\n【憊喘】疲惫而喘息。\n【憊勞】疲劳。\n【憊損】困顿瘦损。\n【憊竭】衰竭。\n【憊駑】衰颓驽钝。\n【憊賴】亦作\"憊懶\"。\n①泼辣，无赖;顽皮。\n② 不好的，坏的。\n【憊懣】困倦烦闷。\n【憊壞】朽坏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惫"},{"id":"glyph-kai-60ed","script":"kai","character":"惭","reading":"cán","description":"惭 cán 亦作\"憀\"。羞愧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惭"},{"id":"glyph-kai-60ef","script":"kai","character":"惯","reading":"guàn","description":"纵容;迁就\n别把孩子给惯坏了\n用同贯”。通;穿\n⒈习以为常的，积久成性的习～。使用～了。这是～例。\n⒉纵容，姑息娇生～养。莫把孩子～坏了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惯"},{"id":"glyph-kai-60f0","script":"kai","character":"惰","reading":"duò","description":"duò：懒，懈怠，与勤”相对懒～。怠～。～性。～慢。将骄卒～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惰"},{"id":"glyph-kai-60f3","script":"kai","character":"想","reading":"xiǎng","description":"xiǎng：(1)动脑筋，思索感～。思～。～法。～象（配置组合而创造出新形象的心理过程）。～入非非。异～天开。幻～。\n(2)推测，认为～必。～见（由推想而知道）。～来（表示只是根据推测，不敢完全肯定）。～当然（凭主观推测，认为事情应该是这样）。不堪设～。\n(3)希望，打算休～。理～。～望。妄～。\n(4)怀念，惦记～念。朝思暮～。\n(5)像云～衣裳花～容。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-想"},{"id":"glyph-kai-60f6","script":"kai","character":"惶","reading":"huáng","description":"huáng：恐惧～怖。～恐。～惧。～～。～惑（疑惧）。～窘。～遽。惊～。～～不可终日。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惶"},{"id":"glyph-kai-60f9","script":"kai","character":"惹","reading":"rě","description":"rě：招引，挑逗招～。～事。～气。～祸。～恼。～是生非。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-惹"},{"id":"glyph-kai-6101","script":"kai","character":"愁","reading":"chóu","description":"chóu：忧虑忧～。～苦。～楚。～烦。～虑。～郁。～闷。～容。～绪。借酒浇～。多～善感。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愁"},{"id":"glyph-kai-6108","script":"kai","character":"愈","reading":"yù","description":"yù：(1)更，越～甚。～加。～发。～益。～演～烈。\n(2)较好，胜过孰～（哪个好）？彼～于此。\n(3)病好了痊～。病～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愈"},{"id":"glyph-kai-6109","script":"kai","character":"愉","reading":"yú；tōu","description":"yú：和悦，快意～快。～悦。欢～。不～之色。\ntōu：古同偷”，苟且敷衍。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愉"},{"id":"glyph-kai-610f","script":"kai","character":"意","reading":"yì","description":"yì：(1)心思～思。～见。～义。～味。～念。～志（为了达到既定目的而自觉努力的心理状态）。注～。同～。～在笔先。～在言外。\n(2)心愿，愿望～愿。愿～。～向。～图。～皆∶～。醉翁之～不在酒”。\n(3)人或事物流露的情态春～。诗～。惬～。情～。～境。\n(4)料想，猜想～料。～想。～外。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-意"},{"id":"glyph-kai-6115","script":"kai","character":"愕","reading":"è","description":"è：(1)惊讶～胎。～异。惊～。错～。闻之～然。\n(2)古同谔”，直言不讳。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愕"},{"id":"glyph-kai-611a","script":"kai","character":"愚","reading":"yú","description":"yú：(1)傻，笨～人。～笨。～蠢。～鲁。～氓（愚蠢的人）。～昧（缺乏知识，文化落后）。～顽。～妄。～不可及。大智若～（有大智慧的人，不卖弄聪明，表面上好像很愚笨，亦作大智如愚”）。\n(2)欺骗，耍～弄人。为人所～。\n(3)谦辞，用于自称～兄。～见。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愚"},{"id":"glyph-kai-611f","script":"kai","character":"感","reading":"gǎn","description":"gǎn：(1)觉出～触。～觉。～性。～知（客观事物通过感觉器官在人脑中的直接反映）。～官。\n(2)使在意识、情绪上起反应；因受刺激而引起的心理上的变化～动。～想。反～∶～。情～。敏～。～染。～召。～慨。～喟。～叹。自豪～。～人肺腑。百～交集。\n(3)对人家的好意表示谢意～谢。～恩。～激。～愧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-感"},{"id":"glyph-kai-6123","script":"kai","character":"愣","reading":"lèng","description":"lèng：(1)发呆，失神～怔。～神儿。发～。\n(2)卤莽，说话做事不考虑效果～头～脑。～冲冲。他～是要去。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愣"},{"id":"glyph-kai-6124","script":"kai","character":"愤","reading":"fèn","description":"充盈,旺盛\n愤怒;怨恨。同忿”\n所以昭炯戒,激众愤\n⒈因不满意而激动发怒～怒。气～得很。激起公～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愤"},{"id":"glyph-kai-6127","script":"kai","character":"愧","reading":"kuì","description":"kuì：羞惭羞～。惭～。～色。～怍（惭愧）。～疚。～赧（因羞愧而脸红）。～悔。问心无～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愧"},{"id":"glyph-kai-613f","script":"kai","character":"愿","reading":"yuàn","description":"大头\n⒈乐意～意。自～。心甘情～。\n⒉希望～望。如～。平生之～。\n⒊仰慕，羡慕名声日闻，天下～。\n⒋迷信者所谓\"对神佛许诺的酬谢\"莫许～。错还～。\n⒌老实，恭谨谨～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-愿"},{"id":"glyph-kai-6148","script":"kai","character":"慈","reading":"cí","description":"cí：(1)仁爱，和善～爱。～善。～悲。～祥。仁～。～和。～眉善目。\n(2)特指慈母”，多用于对人称自己的母亲家～。～闱。～颜。～命。\n(3)对父母的孝敬奉养孝子～孙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慈"},{"id":"glyph-kai-614c","script":"kai","character":"慌","reading":"huāng","description":"huāng：(1)急忙，不沉着～张。～忙。～乱。～急。\n(2)恐惧，不安惊～。～恐。心～意乱。\n(3)表示难以忍受累得～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慌"},{"id":"glyph-kai-614e","script":"kai","character":"慎","reading":"shèn","description":"shèn：(1)小心，当心谨～。不～。～重（zhòng）。～言。～独（在独处时能谨慎不苟）。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慎"},{"id":"glyph-kai-6155","script":"kai","character":"慕","reading":"mù","description":"mù：(1)向往，敬仰～名。羡～。仰～。爱～。景～。敬～。\n(2)思念，依恋思～。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慕"},{"id":"glyph-kai-6162","script":"kai","character":"慢","reading":"màn","description":"màn：(1)迟缓，速度小，与快”相对～车。～件。～腾腾。～条斯理。缓～。迟～。～性。\n(2)态度冷淡，不殷勤，不礼貌～待。轻～。傲～。怠～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慢"},{"id":"glyph-kai-6167","script":"kai","character":"慧","reading":"huì","description":"huì：聪明，有才智聪～。智～。颖～。～黠（聪明而狡猾）。～心。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慧"},{"id":"glyph-kai-6168","script":"kai","character":"慨","reading":"kǎi","description":"kǎi：(1)情绪激昂，愤激愤～。慷～。\n(2)叹息，叹气～叹。感～。\n(3)豪爽，不吝啬～允。～诺。～然。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慨"},{"id":"glyph-kai-6170","script":"kai","character":"慰","reading":"wèi","description":"wèi：(1)使人心里安适～问。～劳。～勉（安慰鼓励）。～唁（慰问死者家属）。～留。～藉。安～。劝～。抚～。\n(2)心安～志（宽慰自己的心情）。宽～。欣～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慰"},{"id":"glyph-kai-6177","script":"kai","character":"慷","reading":"kāng","description":"kāng：〔～慨〕ａ．情绪激昂，如～～激昂”；ｂ．待人热诚，愿意用财物帮助人，如为人～～大方”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-慷"},{"id":"glyph-kai-618b","script":"kai","character":"憋","reading":"biē","description":"biē：(1)气不通～气。～闷（心里不痛快）。～屈。\n(2)勉强忍住他心里有话～不住。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-憋"},{"id":"glyph-kai-618e","script":"kai","character":"憎","reading":"zēng","description":"zēng：恨，厌恶，嫌～恨。～恶。爱～。面目可～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-憎"},{"id":"glyph-kai-6194","script":"kai","character":"憔","reading":"qiáo","description":"qiáo：〔～悴〕a.黄瘦，脸色不好，如颜色～～，形容枯槁”。b.指艰难困苦，如民之～～于虐政”。\n〔～虑〕苦思。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-憔"},{"id":"glyph-kai-61a8","script":"kai","character":"憨","reading":"hān","description":"hān：(1)痴呆～子。～痴。\n(2)天真，纯朴～皮。～直。～实。～厚。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-憨"},{"id":"glyph-kai-61be","script":"kai","character":"憾","reading":"hàn","description":"hàn：(1)失望，心中感到不满足遗～。缺～。～事。～恨。抱～终生。\n(2)怨恨私～。请君释～于宋”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-憾"},{"id":"glyph-kai-61c2","script":"kai","character":"懂","reading":"dǒng","description":"dǒng：了解，明白～事。懵～。他～得这是什么意思。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-懂"},{"id":"glyph-kai-61c8","script":"kai","character":"懈","reading":"xiè","description":"xiè：不紧张～怠。～劲。～气。松～。无～可击。常备不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-懈"},{"id":"glyph-kai-61ca","script":"kai","character":"懊","reading":"ào","description":"ào：烦恼，悔恨～丧（sàng）。～恼。～恨。～悔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-懊"},{"id":"glyph-kai-61d2","script":"kai","character":"懒","reading":"lǎn","description":"疲惫\n⒈怠惰，不肯用劲做～惰。～人∶吃～做。［懒得］不愿意，厌烦～得出门。～得再说。\n⒉疲乏全身发～。\n懒lài 1.嫌恶。参见\"懒学\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-懒"},{"id":"glyph-kai-61e6","script":"kai","character":"懦","reading":"nuò","description":"nuò：软弱无能～夫。～弱。怯～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-懦"},{"id":"glyph-kai-6208","script":"kai","character":"戈","reading":"gē","description":"gē：(1)古代的一种兵器，横刃，用青铜或铁制成，装有长柄干（gān）～。倒（dǎo）～。枕～待旦。\n(2)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戈"},{"id":"glyph-kai-620a","script":"kai","character":"戊","reading":"wù","description":"wù：天干的第五位，用作顺序第五的代称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戊"},{"id":"glyph-kai-620c","script":"kai","character":"戌","reading":"xū","description":"xū：(1)地支的第十一位，属狗。\n(2)用于计时～时（下午七点至九点）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戌"},{"id":"glyph-kai-620e","script":"kai","character":"戎","reading":"róng","description":"róng：(1)古代兵器的总称。\n(2)军队，军事兵～。投笔从～（指文人从军）。～装。～马。\n(3)古代称兵车御～。\n(4)大～功。\n(5)称（方言，音如农”）～有良翰”。\n(6)中国古代称西部民族西～。～狄。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戎"},{"id":"glyph-kai-620f","script":"kai","character":"戏","reading":"xì","description":"假借为麾”。军队中的帅旗\n侧翼\n指歌舞杂技等的表演\n戏剧\n那明湖居本是个大戏园子,戏台\n⒉见xì。\n⒈玩耍～耍。儿～。游～。\n⒉嘲弄，开玩笑～弄。嘲～。前言～耳。\n⒊演剧或歌唱、舞蹈、杂技等表演～剧。～曲。演～。唱～。杂～。看～★～。木偶～。花鼓～。\n戏xī 1.通\"羲\"。 2.通\"巇\"。险峻。 3.古地名。\n戏huī 1.大将之旗。参见\"戏下\"。引申为指挥。\n戏suō 1.酒樽名。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戏"},{"id":"glyph-kai-6210","script":"kai","character":"成","reading":"chéng","description":"chéng：(1)做好，做完～功。完～。～就。～事。～交。～立。～婚。～仁（儒家主张的成就仁德）。～人之美。玉～其事。\n(2)事物发展到一定的形态或状况～形。～性。～人。自学～才。蔚然～风。\n(3)变为长～。变～。\n(4)可以，能行～，就这么办。\n(5)称赞人能力强他办事麻利，真～。\n(6)够，达到一定数量～年累（lěi）月。\n(7)已定的，定形的～规。～俗。～见。～例。～竹在胸。\n(8)十分之一增产三～。\n(9)平定，讲和会于稷，以～宋乱”。\n(10)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-成"},{"id":"glyph-kai-6211","script":"kai","character":"我","reading":"wǒ","description":"wǒ：自称，自己，亦指自己一方～们。～见（我自己的看法）。～辈。～侪（我们）。自～。～盈彼竭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-我"},{"id":"glyph-kai-6212","script":"kai","character":"戒","reading":"jiè","description":"jiè：(1)防备～心。～备。～严。～骄～躁。\n(2)革除不良嗜好～除。～烟。\n(3)佛教律条，泛指禁止做的事～刀。～尺。斋～。\n(4)准备～途。～装。\n(5)古同界”，界限。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戒"},{"id":"glyph-kai-6216","script":"kai","character":"或","reading":"huò","description":"huò：(1)也许，有时，表示不定的词～许。～者（a.也许；b.连词，用在叙述句里，表示选择关系。均亦单用或”）。～然。～则。\n(2)某人，有的人～告之曰。\n(3)稍微不可～缓。不可～忽。不可～缺。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-或"},{"id":"glyph-kai-6218","script":"kai","character":"战","reading":"zhàn","description":"脱我战时袍。\n⒉发抖，极其害怕～栗。打～‘～。胆～心惊。～ ～兢兢。\n①指导战争全局的计划和策略～略上要藐视敌人。\n②有关战争全局的～略物资。\n③〈喻〉决定全局的策略～略措施。\n①作战双方的接触线。\n②指某项工作系统或方面教育～线。思想～线。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-战"},{"id":"glyph-kai-621a","script":"kai","character":"戚","reading":"qī","description":"qī：(1)因婚姻联成的关系亲～。外～。～族。～友。\n(2)忧愁，悲哀～然。凄～。哀～。休～。\n(3)古代兵器，像斧。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戚"},{"id":"glyph-kai-622a","script":"kai","character":"截","reading":"jié","description":"jié：(1)割断，弄断～断。～开。～取。～面。\n(2)量词，段一～儿木头。\n(3)阻拦～住他。～留。～击。～获。\n(4)到一定期限停止～止。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-截"},{"id":"glyph-kai-6233","script":"kai","character":"戳","reading":"chuō","description":"chuō：(1)用硬物尖端触击，刺～穿。\n(2)因猛触硬物而受伤或损坏～伤。～了手。\n(3)竖立，站立把棍子～住。\n(4)图章～记。盖～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戳"},{"id":"glyph-kai-6234","script":"kai","character":"戴","reading":"dài","description":"dài：(1)加在头、面、颈、手等处～帽子。披星～月。～圆履方。不共～天。\n(2)尊奉，推崇，拥护～仰。爱～。拥～。感恩～德。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-戴"},{"id":"glyph-kai-6237","script":"kai","character":"户","reading":"hù","description":"hù：(1)一扇门，门门～。窗～。～枢不蠹。夜不闭～。\n(2)人家～口。～主。门～之见（亦指派别上的成见）。\n(3)会计部门称账册上有业务关系的团体或个人～头。开～。\n(4)门第门当～头。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-户"},{"id":"glyph-kai-623f","script":"kai","character":"房","reading":"fáng","description":"fáng：(1)住人或放东西的建筑物～屋。～产。～舍。～租。库～。楼～。书～。\n(2)结构和作用类似房子的东西蜂～。莲～。心～。\n(3)量词两～儿媳。\n(4)家族的一支大～。长（zhǎng）～。\n(5)星名，二十八宿之一。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-房"},{"id":"glyph-kai-6240","script":"kai","character":"所","reading":"suǒ","description":"suǒ：(1)处，地方住～。哨～。场～。处～。\n(2)机关或其他办事的地方的名称研究～。派出～。\n(3)量词，指房屋一～四合院。\n(4)用在动词前，代表接受动作的事物～部（所率领的部队）。～谓（a.所说的；b.某些人所说的，含不承认意）。无～谓（不关紧要，不关心）。～有。各尽～能。～向无敌。有～不为而后可以有为。\n(5)用在动词前，与前面的为”或被”字相应，表示被动的意思为人～敬。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-所"},{"id":"glyph-kai-6241","script":"kai","character":"扁","reading":"biǎn；piān","description":"biǎn：(1)物体平而薄～豆。～担。～圆。～铲。\n(2)古同匾”，匾额。\npiān：小～舟。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扁"},{"id":"glyph-kai-6247","script":"kai","character":"扇","reading":"shàn；shān","description":"shàn：(1)摇动生风取凉的用具～子。～坠（扇柄下端的装饰物）。～面儿。～形。\n(2)指板状或片状的屏门～。隔～。\n(3)量词，用于门窗等一～门。\nshān：(1)摇动扇子或其它东西，使空气加速流动成风用扇子～。\n(2)鼓动别人去做不应该做的事～动。～风点火。\n(3)用手掌打～耳光。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扇"},{"id":"glyph-kai-624b","script":"kai","character":"手","reading":"shǒu","description":"shǒu：(1)人使用工具的上肢前端～心。棘～（形容事情难办，像荆棘刺手）。着（zhuó）～（开始做，动手）。～不释卷。\n(2)拿着人～一册。\n(3)亲自动手～稿。～迹。～令。～书（a.笔迹；b.亲笔书信）。\n(4)技能、本领～法（技巧，方法）。～段。留一～。\n(5)做某种事情或擅长某种技能的人国～。扒～。生产能～。\n(6)小巧易拿的～枪。～册。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-手"},{"id":"glyph-kai-624d","script":"kai","character":"才","reading":"cái","description":"有才能;有本领\n才力;才能\n①才能怀～不遇。\n②有才能的人奇～。\n③表示以前不久他昨天～走。\n⑤表示本来并不如此的新情况直到天亮，我～知道迷路了。\n⑥表示事情发生得晚或结束得晚你怎么～来\n⑦对比起来表示数量小，次数少，能力差等他刚来北京的时候～三岁。\n⑨姓。\n【才略】政治或军事上的才干和智谋～过人。\n【才气过人】才华超过一般人。\n【才识】才能和见识。\n【才思】指文艺创作的能力～敏捷。\n【才智】才能和智慧。\n【才子】具有很高才干的人。\n才zāi 1.语气词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-才"},{"id":"glyph-kai-624e","script":"kai","character":"扎","reading":"zhā；zā；zhá","description":"zā：(1)捆，缠束～辫子。～腿。\n(2)把儿，捆儿一～线。\nzhā：(1)刺～针。～花。\n(2)驻、扎～营。\n(3)钻扎猛子。\nzhá：〔～挣〕方言，勉强支持（挣”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扎"},{"id":"glyph-kai-6251","script":"kai","character":"扑","reading":"pū","description":"进攻\n拂着;拂拭\n⒈拍，轻打～粉。～蝴蝶。～打帽上的尘土。\n⒉冲，猛打郁香～鼻。～向敌军。～灭苍蝇。\n⒊击为雷电所～。\n扑bǔ 1.见\"扑挑\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扑"},{"id":"glyph-kai-6252","script":"kai","character":"扒","reading":"bā；pá","description":"bā：(1)抓住，把着～车。～墙头儿。\n(2)刨开，挖～坑。～堤。\n(3)剥，脱～皮。～掉伪装。\n(4)拔勿剪勿～。\n(5)拨动～拉。～开草棵。\npá：(1)用耙搂，聚拢～草。\n(2)搔，抓～痒。\n(3)炖烂，煨烂～羊肉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扒"},{"id":"glyph-kai-6253","script":"kai","character":"打","reading":"dǎ；dá","description":"dǎ：(1)击，敲，攻击～击。殴～。～杀。\n(2)放出，发出，注入，扎入～炮。～雷。～信号。～电报。\n(3)做，造～首饰。～家具。\n(4)拨动～算盘。\n(5)揭，破，凿开～破。～井。\n(6)举，提起～灯笼。～起精神。\n(7)涂抹，印，画～蜡。～戳子。\n(8)写出，开出～证明。\n(9)捆，扎～包裹。\n(10)合，结合～伙。～成一片。\n(11)获取，购取～水。～鱼。\n(12)除去～消。～杈。\n(13)定出，计算～算。～腹稿。\n(14)用，采用，使用～比喻。\n(15)玩，玩耍～球。\n(16)截，停，减，退～住。～价儿。\n(17)表示人体发出某种行为动作～手势。\n(18)进行某种活动，从事或担任某种工作～交道。～短工。\n(19)与某些动词结合，基本上保留原动词词义～扫。～扰。\n(20)自，从～哪儿来？\n挨；\ndá：量词，指十二个一～铅笔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-打"},{"id":"glyph-kai-6254","script":"kai","character":"扔","reading":"rēng","description":"rēng：(1)抛，投掷～球。\n(2)丢弃，舍弃～弃。～掉。\n(3)强牵引攘臂而～之。\n(4)摧。\n(5)古同仍”，仍然。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扔"},{"id":"glyph-kai-6258","script":"kai","character":"托","reading":"tuō","description":"tuō：(1)用手掌承着东西两手～着下巴。\n(2)陪衬，铺垫衬～℃～。\n(3)承着器物的东西～盘。\n(4)寄，暂放～身;～迹（均指遁居深山寄身于世外，以逃避世事）。\n(5)请别人代办委～。拜～。嘱～。\n(6)借故推委或躲闪推～。～故。\n(7)信赖，凭借～名。～庇。\n(8)压强单位。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-托"},{"id":"glyph-kai-625b","script":"kai","character":"扛","reading":"káng；gāng","description":"káng：用肩膀承担～枪。\ngāng：两手举东西力能～鼎。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扛"},{"id":"glyph-kai-6263","script":"kai","character":"扣","reading":"kòu","description":"kòu：(1)用圈、环等东西套住或拢住；把门～上。\n(2)衣纽衣～。\n(3)绳结绳～儿。\n(4)把器物口朝下放或覆盖东西把碗～在桌上。\n(5)相符，符合～题（符合题义）。\n(6)强留～押。\n(7)从中减除～除。～发（fā）。\n(8)敲击～人心弦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扣"},{"id":"glyph-kai-6267","script":"kai","character":"执","reading":"zhí","description":"拿;持\n①拿；持。\n②掌握；保持。\n③主管；掌管。\n④选取。\n⑤控制；驾驭。\n⑥执行。\n【执一】专心一志。\n【执友】志同道合的朋友。\n【执中】遵守中正之道，不偏不倚，无过于不及。采取中间的态度。\n【执引】古代送葬时的一种礼节，送葬的宾客须挽牵引柩车的绳索。\n【执业】持书诵习。业，书版。\n【执礼】守礼，遵行礼节。\n【执行】\n①把政策法令或计划等付诸实施。\n②法律用语。公安机关为实现以发生法律效力的判决和裁定所进行的活动。即对刑事案件的被告人执行刑罚，对应负民事责任的当事人责令其履行义务。\n【执拗】固执倔强。\n【执照】由有关行政机关发给的准许作某种行业的凭证。如施工执照；驾驶执照。\n【执迷】固执不悟。\n【执意】坚持自己的意见。\n①拘捕。\n②拿;持。\n③持守。\n④主持;掌管。\n⑤控制;统御。\n⑥操持;从事。\n⑦行;施行。\n⑧固执;坚持。\n⑨依据;遵照。\n⑩判断。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-执"},{"id":"glyph-kai-6269","script":"kai","character":"扩","reading":"kuò","description":"扩大;张开\n广;广阔","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扩"},{"id":"glyph-kai-626b","script":"kai","character":"扫","reading":"sǎo","description":"掠过\n⒈用扫帚等除去尘土、垃圾～地。洒～。\n⒉除掉，消除～除。～盲。～雷。\n⒊迅速掠过，使达到各方面～射。～视人群。\n⒋全，尽，所有的～数归还。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扫"},{"id":"glyph-kai-626c","script":"kai","character":"扬","reading":"yáng","description":"⒈举起，高举～起。～鞭。～帆。\n⒉称颂赞～。颂～。表～。\n⒊振作士气不～。\n⒋显示～兵耀武。\n⒌容貌出众其貌不～。\n⒍飘动，翻腾飞～。风～电激。\n⒎播散，传播～场。～声。宣～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扬"},{"id":"glyph-kai-626d","script":"kai","character":"扭","reading":"niǔ","description":"niǔ：(1)转动，扳转～过脸来。～头。\n(2)拧断强～的瓜不甜。\n(3)拧伤～了腰。\n(4)身体亿转动～动。～捏。～秧歌。\n(5)揪住～打。\n(6)违拗胳臂～不过大腿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扭"},{"id":"glyph-kai-626e","script":"kai","character":"扮","reading":"bàn","description":"bàn：化装～演。打～。装～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扮"},{"id":"glyph-kai-626f","script":"kai","character":"扯","reading":"chě","description":"chě：(1)拉～住不放。牵～别人。\n(2)撕破把信～开。\n(3)不拘形式不拘内容地谈～谎。～闲篇。\n(4)无原则地争论、纠缠、推诿～皮。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扯"},{"id":"glyph-kai-6270","script":"kai","character":"扰","reading":"rǎo","description":"叨扰,指受人财物、饮食\n⒈打搅，侵搅打～。搅～。干～。\n⒉乱天下方～。\n⒊驯服，驯养～化牲畜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扰"},{"id":"glyph-kai-6273","script":"kai","character":"扳","reading":"bān","description":"bān：(1)往下或往里拉～动。～道岔。\n(2)扭转，～回败局。～本（赌博时嬴回输掉的钱）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扳"},{"id":"glyph-kai-6276","script":"kai","character":"扶","reading":"fú","description":"fú：(1)搀，用手支持人或物，使不倒搀～。～正。～老携幼。\n(2)帮助，援助～养。～植。～危济困。\n(3)用手按着或把持着～梯。沙发～手。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扶"},{"id":"glyph-kai-6279","script":"kai","character":"批","reading":"pī","description":"pī：(1)用手掌打～颊（打嘴巴）。\n(2)刮～凿。\n(3)口头或用文字判定是非、优劣、可否～准。～示。～复。～语。～阅。～判。眉～（写在书页天头上的批语）。\n(4)大量～购。～销。\n(5)量词，用于大宗的货物或数量众多的事物一～货物。\n(6)棉麻等未捻成线、绳时的细缕线～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-批"},{"id":"glyph-kai-627c","script":"kai","character":"扼","reading":"è","description":"è：(1)用力掐着，抓住～杀。～腕（用一只手握住另一只手，表示振奋、失意、惋惜等情绪）。力能～虎。\n(2)抓要点，简要～要。\n(3)把守，控制～制。～喉拊背（喻控制要害，制敌于死命）。\n(4)古同轭”，牛马等拉东西时架在脖子上的器具。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-扼"},{"id":"glyph-kai-627e","script":"kai","character":"找","reading":"zhǎo","description":"zhǎo：(1)寻求，想要得到寻～。～人。～物。\n(2)退回，补足～钱。～平。～齐。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-找"},{"id":"glyph-kai-627f","script":"kai","character":"承","reading":"chéng","description":"chéng：(1)在下面接受，托着～重。～受。\n(2)担当，应允～担。～当。～包。～做。～认。\n(3)受到，蒙受～蒙。～恩（蒙受恩泽）。\n(4)继续，接联继～。～平（指社会比较持久安定的局面）。～前启后。\n(5)顺从，迎合奉～。～颜候色（顺着别人颜色办事）。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-承"},{"id":"glyph-kai-6280","script":"kai","character":"技","reading":"jì","description":"jì：才能，手艺～术。～巧。～艺。～能。～法。黔驴～穷。雕虫小～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-技"},{"id":"glyph-kai-6284","script":"kai","character":"抄","reading":"chāo","description":"chāo：(1)誊写，照原文写～本。～写。～袭。传～。\n(2)搜查而没收～没（mò）。～家。～斩。\n(3)走简捷的路～近。～小道。包～。\n(4)同绰2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抄"},{"id":"glyph-kai-628a","script":"kai","character":"把","reading":"bǎ；bà","description":"bǎ：(1)拿，抓住～酒（拿着酒杯）。～玩（拿着赏玩）。\n(2)控制，掌握～握。～舵。\n(3)看守～守。～门儿。\n(4)自行车、手推车等的手柄车～。\n(5)可以用手拿的小捆秫秸～儿。\n(6)专权，一手独揽～持大权。\n(7)从后托起小孩两腿使之大小便的动作～尿。\n(8)介词，义为拿，处置，致使你能～他怎么样。\n(9)量词。\n(10)结盟拜～子。～兄弟。\nbà：(1)物体上便于手拿的部分刀～儿。\n(2)被人作为说笑资料的言行话～儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-把"},{"id":"glyph-kai-6291","script":"kai","character":"抑","reading":"yì","description":"yì：(1)压，压制～制。～止。压～。～强扶弱。～扬（a.音调的高低起伏；b.沉浮；c.褒贬）。\n(2)忧闷～郁。～塞（sè）。\n(3)文言连词（a.表选择，相当于或是、还是，如～或”；b.表转折，相当于可是、但是，如多则多矣，～君似鼠”）。\n(4)文言发语词～齐人不盟，若之何”。\n(5)古同噫”，叹词。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抑"},{"id":"glyph-kai-6292","script":"kai","character":"抒","reading":"shū","description":"shū：(1)发出，表达，倾吐～情。～怀。～愤。～发。各～己见。直～胸臆。\n(2)挹取，挹注。\n(3)古同纾”，解除。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抒"},{"id":"glyph-kai-6293","script":"kai","character":"抓","reading":"zhuā","description":"zhuā：(1)用指或爪挠～挠。～痒。\n(2)用手或爪拿取～药。～彩。\n(3)捉捕～贼。～间谍。\n(4)把握住，不放过～工夫。\n(5)特别注意，加强领导～重点。\n(6)引人注意他一上场就～住了观众。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抓"},{"id":"glyph-kai-6295","script":"kai","character":"投","reading":"tóu","description":"tóu：(1)抛，掷，扔（多指有目标的）～篮。～弹（dàn）。\n(2)跳进去～河。自～罗网。\n(3)放进去，送进去～入。～资。～标。\n(4)走向，进入～宿（找地方住宿）。～奔。～靠。～降。～师（从师学习）。～诉。\n(5)发向～射。～影。\n(6)寄，递送～递。～稿。\n(7)合～合。意气相～。\n(8)临，在…以前～明。～暮（天黑以前）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-投"},{"id":"glyph-kai-6296","script":"kai","character":"抖","reading":"dǒu","description":"dǒu：(1)振动，甩动～去身上的土。\n(2)哆嗦，战栗发～。颤～。\n(3)称人突然发迹而有钱有势（多含讥讽意）这两年～起来了。\n〔～擞〕振作，振奋，如～～精神”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抖"},{"id":"glyph-kai-6297","script":"kai","character":"抗","reading":"kàng","description":"kàng：(1)抵御～击。～争。～拒。抵～。顽～。\n(2)拒绝～议。～上。～命。～税。\n(3)对等～衡（力量不相上下的对抗）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抗"},{"id":"glyph-kai-6298","script":"kai","character":"折","reading":"shé；zhē；zhé","description":"zhē：翻转，倒腾～腾。～跟头。～个儿。\n合；搭；装；\nzhé：(1)断，弄断～断。～桂（喻科举及第）。～戟沉沙（形容惨重的失败）。\n(2)幼年死亡夭～。\n(3)弯转，屈曲曲～。转～。周～。～中（对不同意见采取调和态度。亦作折衷”）。\n(4)返转，回转～返。\n(5)损失损兵～将。\n(6)挫辱～磨。挫～。百～不挠。\n(7)减少～寿（减少寿命）。～扣。\n(8)抵作，对换，以此代彼～合。～价（把实物折合成钱）。\n(9)心服～服（a.信服；b.说服）。\n(10)戏曲名词，杂剧一本分四折，一折等于后来的一出～子戏。\n(11)判决～狱。\n合；搭；装；\nshé：(1)断，绳子～了。\n(2)亏损～本生意。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-折"},{"id":"glyph-kai-629a","script":"kai","character":"抚","reading":"fǔ","description":"扶持;护持\n⒈扶持，保护，养育～养。～育。～其老弱。\n⒉慰问～恤。安～。优～。\n⒊按摩，轻轻地摸～摩。～摸。\n⒋拍，击～背。～掌欢笑。\n抚mó 1.仿效。 2.临摹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抚"},{"id":"glyph-kai-629b","script":"kai","character":"抛","reading":"pāo","description":"pāo：(1)投，扔～掷。～撒（亦作抛洒”）。～售。\n(2)舍弃，丢下～弃。～荒（任由土地荒芜，不继续耕种）。～却。～头露面。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抛"},{"id":"glyph-kai-62a0","script":"kai","character":"抠","reading":"kōu","description":"抓牢\n⒈使用手指或细小的东西挖～个小孔。把钉子从壁缝中～出来。〈引〉向片面狭窄的方面去深求专～字眼。死～条文。\n⒉雕刻～花纹。\n⒊吝啬，小气此人太～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抠"},{"id":"glyph-kai-62a1","script":"kai","character":"抡","reading":"lún","description":"挥动或挥舞\n任意浪费家财\n猛拉\n抡动\n抡动他的手臂\n抡眉竖目","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抡"},{"id":"glyph-kai-62a2","script":"kai","character":"抢","reading":"qiǎng","description":"撞;碰;触\n推,搡\n逆;顶;挡\n创伤,伤\n代替\n冲;闯\n抢出一条吊桶大小,雪花也似\n⒈夺，硬拿～夺。～球。～劫。\n⒉赶快，争时间～先。～救。～收～种。\n⒈通\"戗\"。逆，反方向。\n⒉碰，撞～壁。以头～地。\n抢qiàng 1.同\"鎗\"。在器物上填嵌金银等饰物。参见\"抢金\"。 2.同\"呛\"。因异物刺激气管引起气逆咳嗽。\n抢chéng 1.见\"抢攘\"。\n抢chēng 1.见\"搀抢\"。 2.美丽，漂亮。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抢"},{"id":"glyph-kai-62a4","script":"kai","character":"护","reading":"hù","description":"贯铁絙护之。\n爱护\n袒护;包庇\n⒈保卫，照顾～卫。～厂。～航。～理。保～。爱～。〈引〉掩盖，包庇莫～短。你不要～着他。\n①外交机构发给本国公民证明身份的执照，在进入另一国停留时使用。\n②旧时旅行或运货时所带的政府机关证明文件。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-护"},{"id":"glyph-kai-62a5","script":"kai","character":"报","reading":"bào","description":"闻死刑之报,君为流涕。\n报答,报酬\n②告诉～信。\n③回答～以微笑。\n④报答，用实际行动表示感谢～国。\n⑤报复～仇。\n⑥报应一～一还一～。\n⑦报纸日～、周～。\n⑧某些刊物画～、学～。\n⑨用文字报道消息或发表意见的某些东西喜～、黑板～。\n⑩电报发～机。\n【报偿】报答和补偿。\n【报仇雪恨】采取行动来打击仇人，解除怨恨。雪洗除。\n【报酬】因使用别人的人力、物力等而付给别人的钱或物一心工作，不计～。\n【报告文学】记叙性散文中通讯、特写等体裁的总称。取材于现实生活中具有典型意义的真人真事，进行适当的艺术加工，迅速及时地反映当时的事件，带有新闻性、政治性和\n文学性的特点。\n【报捷】报告好消息。\n【报警】向治安机关报告危急情况或向有关方面或人发出紧急信号～器。\n【报警系统】发生危险情况时报警的装置系统。通常是开环控制系统，由报警探测器和指示器两个部分组成。如电子报警系统等。\n【报人】新闻工作者。\n【报丧】把某人去世的消息通知死者的亲友。\n【报喜不报忧】只汇报成绩而不说缺点和问题。\n【报晓】用声音告诉人天亮了金鸡～。\n【报效】为报答恩情而为之尽力。～祖国。\n【报应】佛教用语。原指善有善报，恶有恶报，后来专指种恶因得恶果做坏事迟早会得到～的。\n报fù 1.急速。 2.往，去。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-报"},{"id":"glyph-kai-62ab","script":"kai","character":"披","reading":"pī","description":"pī：(1)覆盖在肩背上～星戴月。\n(2)穿戴～挂。～甲。\n(3)打开，散开～襟。～阅。～露（发表，公布，表露）。所向～靡。\n(4)劈开，裂开竹竿～了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-披"},{"id":"glyph-kai-62ac","script":"kai","character":"抬","reading":"tái","description":"tái：(1)举，仰～头。～手（喻通融宽恕）。\n(2)合力共举，提高～杠。～爱。～轿子（喻为有权势的人捧场）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抬"},{"id":"glyph-kai-62b1","script":"kai","character":"抱","reading":"bào","description":"bào：(1)用手臂围住拥～。～小孩儿∠～。～残守缺（形容保守，不知进取）。\n(2)围绕，环绕山环水～。～厦（房屋前面加出来的门廊，亦指后面毗连的小房子）。\n(3)胸怀愿望，志向～负。\n(4)心里存着，怀有～怨。～恨。～歉。～憾。～病。\n(5)密合衣服～身儿。\n(6)把他人的子女收养为自己的子女～养。\n(7)量词表示两臂合围的量一～草。\n(8)孵～窝。～小鸡。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抱"},{"id":"glyph-kai-62b5","script":"kai","character":"抵","reading":"dǐ","description":"dǐ：(1)挡，拒，用力对撑着～挡。～制。～抗。～赖。\n(2)顶撞，冲突，矛盾～触。\n(3)代替，相当，顶替～押。～偿。～充。～还（huán）。\n(4)到达～京。～临。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抵"},{"id":"glyph-kai-62b9","script":"kai","character":"抹","reading":"mò；mǒ；mā","description":"mǒ：(1)涂涂～。～粉（喻美化或掩饰）。～黑（喻丑化）。～子（瓦工用来抹灰泥的器具。亦称抹刀”）。\n(2)揩，擦～拭。哭天～泪。\n(3)除去，勾掉，不计在内～煞。\n(4)轻微的痕迹林梢一～青如画”。一～余晖。\n擦；揩；拭；涂；\nmò：(1)把和好了的泥或灰涂上后弄平～墙。～石灰。\n(2)紧靠着绕过去～头。～身。\n(3)用手指轻按，奏弦乐指法的一种。\n擦；揩；拭；涂；\nmā：(1)擦～桌子。\n(2)按着向下移动、除去～不下脸来（碍于脸面或情面）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抹"},{"id":"glyph-kai-62bc","script":"kai","character":"押","reading":"yā","description":"yā：(1)在文书、契约上签名或画记号画～。签～。\n(2)把财物交给人作保证～租。～金。～当（dàng）。典～。\n(3)拘留看（kān）～。拘～。～禁。\n(4)跟随看管～送。～运。\n(5)同压”，用于押宝”、押队”、押韵”。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-押"},{"id":"glyph-kai-62bd","script":"kai","character":"抽","reading":"chōu","description":"chōu：(1)把中间的取出把信～出。\n(2)从事物中提出一部分～签。～调（diào）。～查。～头。～薪止沸。\n(3)吸～烟。～水。～泣。～咽。\n(4)概括～象。～演。\n(5)减缩～缩。\n(6)引出，长出～青。～芽。～穗。～纱。\n(7)用细长的、软的东西打用鞭子～。\n(8)痉挛～搐。～风。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-抽"},{"id":"glyph-kai-62c2","script":"kai","character":"拂","reading":"fú；bì","description":"fú：(1)拭，掸去～拭。～尘。\n(2)轻轻擦过～晓。春风～面。微风～煦。\n(3)甩动，抖动～袖而去。\n(4)违背，不顺忠言～耳。～逆。\nbì：古同弼”，辅助。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拂"},{"id":"glyph-kai-62c4","script":"kai","character":"拄","reading":"zhǔ","description":"zhǔ：(1)用手扶着杖或棍支持身体的平衡～着拐棍走。\n(2)讽刺，驳倒（云）既论难，连～五鹿君”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拄"},{"id":"glyph-kai-62c5","script":"kai","character":"担","reading":"dān；dǎn","description":"dǎn：同掸”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-担"},{"id":"glyph-kai-62c6","script":"kai","character":"拆","reading":"chāi；cā","description":"chāi：(1)把合在一起的弄开～信。～洗。～卸。～字。\n(2)分散，毁掉～散。～台。～迁。\n〔～白〕方言，流氓骗取财物。\n搭；装；\ncā：方言，排泄（大小便）～烂污（喻不负责任）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拆"},{"id":"glyph-kai-62c7","script":"kai","character":"拇","reading":"mǔ","description":"mǔ：(1)手、脚的大指～指。\n(2)划拳（亦称猜拳”），酒令的一种～战。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拇"},{"id":"glyph-kai-62c9","script":"kai","character":"拉","reading":"lā；lá","description":"lā：(1)牵，扯，拽～车。～网。～下马（喻使某人下台）。\n(2)用车载运～货。\n(3)使延长～延。～伸。\n(4)排泄粪便～屎。\n(5)联络～拢。～帮结伙。\n(6)摧折摧枯～朽。\n(7)带领转移把部队～出去。\n(8)牵引乐器的某一部分使乐器发出声音～小提琴。\n(9)抚养子女～扯。\n(10)帮助他有困难，～他一把。\n推；\nlá：(1)割，用刀把东西切开一道缝或切断手上～了一个口子。\n(2)闲谈～话。～家常。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拉"},{"id":"glyph-kai-62cc","script":"kai","character":"拌","reading":"bàn；pàn","description":"bàn：(1)搅和搅～。～和（huò）。～面。～菜。～草料。\n(2)口角～嘴。\npàn：(1)古同拚”，舍弃。\n(2)古同判”，分开。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拌"},{"id":"glyph-kai-62cd","script":"kai","character":"拍","reading":"pāi","description":"pāi：(1)用手掌打～击。～掌。～抚。～案叫绝。\n(2)浪涛冲击～岸。\n(3)拍打东西的用具～子（亦是计算乐音长短的单位）。\n(4)乐曲的节奏～节。\n(5)摄影～摄。～照。～片子。\n(6)发出～发。～电报。\n(7)阿谀，巴结～马屁。吹吹～～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拍"},{"id":"glyph-kai-62ce","script":"kai","character":"拎","reading":"līn","description":"līn：提～水。～提包。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拎"},{"id":"glyph-kai-62d0","script":"kai","character":"拐","reading":"guǎi","description":"guǎi：(1)转折～弯。\n(2)骗～骗。～卖。\n(3)走路不稳，跛他走路一～一～的。\n(4)走路时帮助支持身体的棍～棍。双～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拐"},{"id":"glyph-kai-62d2","script":"kai","character":"拒","reading":"jù；jv","description":"jù：(1)抵挡，抵抗～守。～敌。抗～。\n(2)不接受～绝。～谏（拒绝劝谏）。来者不～。\n(3)古同矩”，方阵。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拒"},{"id":"glyph-kai-62d3","script":"kai","character":"拓","reading":"tuò；tà；zhí","description":"tuò：(1)开辟，扩充～荒。开～。～展。～落（a.宽广；b.潦倒失意。亦作落拓”）。\n(2)以手推物孔子之劲，能～国门之关，而不肯以力闻”。\n(3)姓。\ntà：在刻铸有文字或图像的器物上，涂上墨，蒙上一层纸，捶打后使凹凸分明，显出文字图像来～印。～本。～片。\nzhí：古同摭”，拾取。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拓"},{"id":"glyph-kai-62d4","script":"kai","character":"拔","reading":"bá","description":"bá：(1)抽，拉出，连根拽出～腿。～草。～牙。～苗助长。\n(2)夺取军事上的据点连～数城。\n(3)吸出～毒。～火罐儿。\n(4)选取，提升提～。～擢。\n(5)超出，高出海～。挺～。～地（山、树、建筑物等高耸在地面上）。～尖儿。出类～萃。\n(6)把东西放在凉水里使变凉把西瓜放在冰水里～一～。\n(7)改变坚韧不～。心志不可～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拔"},{"id":"glyph-kai-62d6","script":"kai","character":"拖","reading":"tuō","description":"tuō：(1)牵引，拉，拽～车。～船。～累（lěi）。～儿带女。\n(2)耷拉着～着辫子。\n(3)延长时间～延。～欠。～债。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拖"},{"id":"glyph-kai-62d7","script":"kai","character":"拗","reading":"niù；ǎo；ào","description":"ǎo：弯曲使断，折竹竿～断了。\nào：不顺，不顺从～口。～口令。\nniù：固执，不驯顺执～。～不过他。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拗"},{"id":"glyph-kai-62d8","script":"kai","character":"拘","reading":"jū；gōu；jv","description":"jū：(1)逮捕或扣押～捕。～系。～留。～拿。～囚。～禁。～押。\n(2)限，限制～束。～谨。不～小节。\n(3)固执，不变通～泥。～礼。～迂。\ngōu：遮蔽凡为长者粪之礼，必加帚于箕上，以袂～而退”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拘"},{"id":"glyph-kai-62d9","script":"kai","character":"拙","reading":"zhuō","description":"zhuō：(1)笨，不灵巧笨～。弄巧成～。～劣。\n(2)谦辞，称自己的～作。～见。～笔。～著。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拙"},{"id":"glyph-kai-62db","script":"kai","character":"招","reading":"zhāo","description":"zhāo：(1)打手势叫人来～唤。～呼。～手上车。\n(2)用公开的方式使人来～集。～收。～纳。～贤。～聘。～兵买马。\n(3)应接～待宾客。\n(4)引来～惹。～引。～揽。～致。\n(5)承认自己的罪行～供。～认。不打自～。\n(6)同着3”①②。\n(7)摇动～摇（故意张大声势，引人注意）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-招"},{"id":"glyph-kai-62dc","script":"kai","character":"拜","reading":"bài","description":"bài：(1)表示敬意的礼节～手（古代男子跪拜礼的一种）。～忏。礼～。回～。\n(2)恭敬地～托。～谢。～读。～别。～谒（a.拜见；b.瞻仰陵墓、碑碣）。\n(3)行礼棕～年。～寿。\n(4)用一定的礼节授与某种名义或职位，或结成某种关系～将（jiàng）。～相（xiàng）。～师。～把子。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拜"},{"id":"glyph-kai-62df","script":"kai","character":"拟","reading":"nǐ","description":"类似;比拟\n⒈准备，打算～办。～往广州。\n⒉起草，初步设想～稿。～订。草～计划。\n⒊模仿，仿照模～。～制。\n⒋比，比划，用兵器作杀人的样子比～。举剑～之。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拟"},{"id":"glyph-kai-62e2","script":"kai","character":"拢","reading":"lǒng","description":"总计;合计\n梳理;整理\n傍靠\n接近\n弹奏弦乐器的一种指法。用指在弦上上下按捺\n轻拢慢捻抹复挑\n⒈总合，合上，聚集～总∠～。～到一起。\n⒉靠近，船只靠岸靠～。拉～。谈得～。～岸。\n⒊收束，使不放松～紧。～住。\n⒋梳，梳理～发。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拢"},{"id":"glyph-kai-62e3","script":"kai","character":"拣","reading":"jiǎn","description":"同捡”。拾起\n通过有利条件或优势获得\n拣佛烧香\n⒈选择，挑选～好的。～挑重担。\n⒉拾取～柴草。～稻穗。～废物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拣"},{"id":"glyph-kai-62e5","script":"kai","character":"拥","reading":"yōng","description":"簇拥\n环抱\n⒉围着～炉而坐。前呼后～。\n⒊阻塞，聚到一起人多～挤。夹道都人～。\n⒋持有～有。\n⒌保卫，护卫～卫。\n⒍赞成，忠诚爱戴，竭力支持～护。～戴。～军优属。～护社会主义。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拥"},{"id":"glyph-kai-62e6","script":"kai","character":"拦","reading":"lán","description":"拦lán不让通过；阻挡。\n【拦挡】不使通过；使中途停止。\n【拦挡木】拦挡行人、车辆等的横杆或横木。\n【拦柜】柜台。也叫拦柜。\n【拦河坝】拦截河水的建筑物。\n【拦截】中途阻挡，不让通过。\n【拦路】拦住去路。\n【拦路虎】过去指拦路打劫的匪徒，现在指前进道路上的障碍和困难。\n【拦蓄】修筑堤坝把水流拦住并蓄积起来。\n【拦阻】阻挡。\n①遮拦，阻拦。\n②当，正对。\n③挡住其它方向，沿着一条路线驱赶牛羊等。引申指放牧。\n④通\"欄\"。栏干;拦圈。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拦"},{"id":"glyph-kai-62e7","script":"kai","character":"拧","reading":"nǐng","description":"扭;绞\n团聚\n用力扭转\n别扭;意见相互不一致\n颠倒,不好,\n⒈扭转，控制住物体的一部分而旋转～紧瓶盖。～开龙头放水。\n⒉〈方〉相反，不顺弄～了。这件事，叫他俩闹～了。\n⒈握住物体的两端，各向相反的方向使力扭绞～绳索。\n⒉用手指夹住皮肉转～了他一下。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拧"},{"id":"glyph-kai-62e8","script":"kai","character":"拨","reading":"bō","description":"拨动东西;分开;拨开\n①手脚或棍棒等横着发力～开众人。\n②分出一部分发给；调配调～。\n③掉转～马回营。\n④量词。用于人的分组；伙下午来了一～人。\n【拨乱反正】澄清混乱，恢复正常。\n【拨冗】客套话。推开繁重的事务，挤出时间望～赐教。\n拨fá 1.大盾。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拨"},{"id":"glyph-kai-62e9","script":"kai","character":"择","reading":"zé","description":"⒈挑拣，挑选选～。～良友。不～手段。\n择yì 1.人名用字。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-择"},{"id":"glyph-kai-62ec","script":"kai","character":"括","reading":"kuò；guā","description":"kuò：(1)扎，束～发（束起头发）。～约肌。\n(2)包容包～。概～。总～。囊～。\nguā：榨取，搜求搜～（亦作搜刮”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-括"},{"id":"glyph-kai-62ed","script":"kai","character":"拭","reading":"shì","description":"拭shì擦擦～。～目而待。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-拭"}];
